record.field:
purchase_activity_type_ids = env['mail.activity.type'].search([ ('res_model', '=', 'purchase.order'), ]).ids
purchase_activity_domain = [ ('active', '=', True), ('res_model', '=', 'purchase.order'), ('activity_type_id', 'in', purchase_activity_type_ids), ]
purchase_orders = env['purchase.order'].search([ ('state', '!=', 'cancel'), ('activity_ids', 'any', purchase_activity_domain), ], limit=50, order='create_date asc, id asc')
for purchase_order in purchase_orders: purchase_activity = env['mail.activity'].search( purchase_activity_domain + [('res_id', '=', purchase_order.id)], order='create_date desc, id desc', limit=1, ) if purchase_activity: purchase_activity.action_feedback()
batch_activity_type_ids = [ env.ref( 'fmcg_business_automation.mail_activity_type_review_transfer_batch' ).id, env.ref( 'fmcg_business_automation.mail_activity_type_confirm_transfer_batch' ).id, env.ref( 'fmcg_business_automation.mail_activity_type_validate_transfer_batch' ).id, env.ref( 'fmcg_business_automation.mail_activity_type_cancel_transfer_batch' ).id, ] batches = env['stock.picking.batch'].search([ ('is_wave', '=', False), ('state', 'not in', ['done', 'cancel']), ], limit=50, order='create_date asc, id asc')
for batch in batches: activity = env['mail.activity'].search([ ('active', '=', True), ('res_model', '=', 'stock.picking.batch'), ('res_id', '=', batch.id), ('activity_type_id', 'in', batch_activity_type_ids), ], order='create_date desc, id desc', limit=1)
if not activity: raise UserError( 'Batch %s (state: %s) chưa hoàn tất nhưng không có ' 'Activity workflow để xử lý.' % (batch.display_name, batch.state) )
activity.action_feedback() check_availability_type = env.ref( 'fmcg_business_automation.' 'mail_activity_type_check_picking_availability' )
activity_type_ids = env['ir.model.data'].search([ ('module', '=', 'fmcg_business_automation'), ('model', '=', 'mail.activity.type'), ('res_id', '!=', check_availability_type.id), ]).mapped('res_id')
pickings = env['stock.picking'].search([ ('state', 'not in', ['done', 'cancel']), ('activity_ids.activity_type_id', 'in', activity_type_ids), ], limit=50, order='create_date asc, id asc')
for picking in pickings: activity = env['mail.activity'].search([ ('res_model', '=', 'stock.picking'), ('res_id', '=', picking.id), ('activity_type_id', 'in', activity_type_ids), ], order='create_date desc, id desc', limit=1)
if not activity: if picking.state == 'draft': confirm_draft_type = env.ref( 'fmcg_business_automation.mail_activity_type_confirm_draft_picking' ) picking.activity_schedule( activity_type_id=confirm_draft_type.id, summary='Confirm draft stock picking', user_id=env.user.id, ) continue elif picking.state == 'assigned': validate_type = env.ref( 'fmcg_business_automation.mail_activity_type_validate_assigned_picking' ) picking.activity_schedule( activity_type_id=validate_type.id, summary='Validate assigned stock picking', user_id=env.user.id, ) continue raise UserError( 'Picking %s (state: %s) chưa hoàn tất nhưng không có Activity để xử lý.' % (picking.name, picking.state) )
activity.action_feedback()

